WITH ACS_Admissions AS (
  -- Identify admissions for patients with ACS (Acute Coronary Syndrome)
  SELECT
    a.subject_id,
    a.hadm_id
  FROM `physionet-data.mimiciv_3_1_hosp.admissions` AS a
  JOIN `physionet-data.mimiciv_3_1_hosp.diagnoses_icd` AS d
    ON a.hadm_id = d.hadm_id
  JOIN `physionet-data.mimiciv_3_1_hosp.d_icd_diagnoses` AS di
    ON d.icd_code = di.icd_code AND d.icd_version = di.icd_version
  WHERE
    di.long_title LIKE '%Acute Coronary Syndrome%'
    OR di.long_title LIKE '%Myocardial Infarction%'
    OR di.long_title LIKE '%Unstable Angina%'
